# Lesson 8 of MKTG90037: the Value Proposition Canvas (Week 3, second half). Brand: Coles (FY26 facts, with the shopper's side
# as the course's reading). Instruments: fit board (Connect), what kind of gain or job (Tag).
from mk import *  # noqa: F403


def L08(CID):
    SK = 'mk.vpc'
    left = [dict(id='p1', label=T('Pain: “I have no time to do a big shop”', '痛点：“我没时间做一次大采购”')), dict(id='p2', label=T('Pain: “I worry the basket costs too much”', '痛点：“我担心这一篮东西太贵”')),
            dict(id='g1', label=T('Gain: “I want fresh food I can trust is Australian”', '收益：“我想要能放心的澳大利亚新鲜食品”')), dict(id='g2', label=T('Gain: “I want to be rewarded for shopping here”', '收益：“我想为在这里买东西得到回报”')),
            dict(id='g3', label=T('Gain: “I would love something special to serve guests”', '收益：“我很想有点特别的东西招待客人”'))]
    right = [dict(id='r1', label=T('Pain reliever: same-day delivery from fulfilment centres', '痛点缓解：从履约中心当日送达')), dict(id='r2', label=T('Pain reliever: Own Brand ranges, with cost savings reinvested in value', '痛点缓解：自有品牌系列，成本节省再投入价格')),
             dict(id='c1', label=T('Gain creator: Own Brand fresh beef, chicken, lamb, pork, milk and eggs, 100% Australian-grown', '收益创造：自有品牌的新鲜牛肉、鸡肉、羊肉、猪肉、牛奶和鸡蛋，100% 澳大利亚产')), dict(id='c2', label=T('Gain creator: Flybuys', '收益创造：Flybuys')),
             dict(id='c3', label=T('Gain creator: exclusive ranges with partners such as M&S, Grill’d and Gami', '收益创造：与 M&S、Grill’d、Gami 等伙伴合作的独家系列'))]
    pairs = [['p1', 'r1', T('The pain is time; the reliever removes the trip.', '痛点是时间；缓解方案省掉了这趟路。')], ['p2', 'r2', T('The pain is cost; the reliever targets cost.', '痛点是成本；缓解方案针对成本。')],
             ['g1', 'c1', T('The gain is trust in origin; the creator states the origin.', '收益是对产地的信任；创造方案写明了产地。')], ['g2', 'c2', T('The gain is a reward; the creator is the loyalty programme.', '收益是回报；创造方案就是忠诚计划。')],
             ['g3', 'c3', T('The gain is special; the creator brings something shoppers did not have.', '收益是特别；创造方案带来购物者以前没有的东西。')]]
    cats = [dict(id='req', label=T('Required', '必需')), dict(id='exp', label=T('Expected', '期望')), dict(id='des', label=T('Desired', '渴望')), dict(id='unx', label=T('Unexpected', '意外'))]
    items = [
        dict(text=T('A phone must be able to make a call.', '手机必须能打电话。'), cat='req', why=T('Without it the solution does not work at all.', '没有它，方案根本不能用。')),
        dict(text=T('A phone is expected to look good, though it would work without that.', '人们期望手机好看，尽管不好看也能用。'), cat='exp', why=T('Expected even though not required.', '不是必需的，但被期望。')),
        dict(text=T('It would be nice if the phone linked seamlessly with other devices.', '要是手机能与其他设备无缝联动就好了。'), cat='des', why=T('Beyond what is expected: nice to have.', '超出期望：有了更好。')),
        dict(text=T('Before dual SIMs existed, few customers would have thought to ask for one.', '双卡出现之前，很少有顾客想到要它。'), cat='unx', why=T('The customer would not come up with it even when asked.', '即使被问到，顾客也想不到。')),
    ]
    return dict(
        id=f'{CID}-vpc',
        title=T('Is what we offer what the customer actually needs?', '我们提供的，是顾客真正需要的吗？'),
        description=T('Match a shopper’s jobs, pains and gains to what Coles offers on the Value Proposition Canvas, and learn the four kinds of gain.', '在价值主张画布上，把购物者的任务、痛点和收益与 Coles 的产品对上，并认识四种收益。'),
        minutes=35,
        skills=[{'id': SK, 'name': T('Explaining and applying the Value Proposition Canvas', '解释并应用价值主张画布')}],
        misconceptions=[
            {'id': 'vpc-list-features', 'description': T('the value map should list every feature the firm has', '价值图应该列出企业所有的功能')},
            {'id': 'pains-are-complaints', 'description': T('pains are only what customers complain about', '痛点就是顾客抱怨的东西')},
        ],
        steps=[
            read('puzzle', T('A good product, nobody’s problem', '一个好产品，却不解决任何人的问题'),
                 p(T("Many products fail not because they are bad but because they solve a problem nobody has, or leave the one they should have solved. The canvas of the last lesson says **who** and **what promise**; the **Value Proposition Canvas** checks that the offer **fits** what the customer is really trying to do.",
                     "很多产品失败，不是因为不好，而是因为解决了没人有的问题，或者漏掉了本该解决的问题。上一课的画布说的是**为谁**、**什么承诺**；**价值主张画布**检验的是这个提供是否**契合**顾客真正想完成的事。")),
                 chapter=CH['puzzle']),
            predict('guess', SK, T("A shopper complains: “Delivery is too slow.” Which is the real job, pain and gain behind it?", "一位购物者抱怨：“送货太慢。”这背后真正的任务、痛点和收益是什么？"),
                    [(T("Job: get the shopping home; pain: time lost; gain: an evening free", "任务：把东西买回家；痛点：浪费时间；收益：多出一个晚上"), True),
                     (T("Job: complain; pain: slowness", "任务：抱怨；痛点：慢"), T("The complaint is the visible tip of the pain, not the job.", "抱怨只是痛点露出来的尖，不是任务。")),
                     (T("Nothing: it is a feature request", "什么都不是：这是功能需求"), T("A feature request names a solution; the canvas looks at the job under it.", "功能需求说的是解决办法；画布看的是它下面的任务。")),
                     (T("Job: pay less", "任务：少花钱"), T("The words say time, not cost.", "字面说的是时间，不是成本。"))],
                    T("Look **under** the words to the job (what they are trying to get done), the pains that block it, and the gains they want. That is the right-hand side of the canvas.", "要**透过**字面去看任务（想完成什么）、阻碍它的痛点、想要的收益。这就是画布的右半边。")),
            read('touch', T('Fit the board', '把画布配上'),
                 p(T("Left: five things a Coles shopper might feel, read as pains and gains (the course’s reading). Right: five things Coles actually does, from its FY26 results and its own pages.", "左边：Coles 购物者可能有的五种感受，读作痛点和收益（本课程的解读）。右边：Coles 实际做的五件事，来自 2026 财年业绩和公司自己的页面。")),
                 connect(T('Five shopper pains and gains to connect to the Coles pain relievers and gain creators that answer them.', '五条购物者的痛点与收益，连到回应它们的 Coles 痛点缓解与收益创造。'), left, right, pairs, no=T('That relieves a different pain, or creates a different gain.', '那个缓解的是另一种痛点，或创造的是另一种收益。'),
                         done=T("A **fit** is a pain relieved or a gain created for a job that matters. Offers with no pair on the left (features nobody needs) are waste; pains and gains with no pair on the right are openings.", "**契合**就是为一件重要的任务缓解了痛点或创造了收益。右边没有对应左边的提供（没人需要的功能）是浪费；左边没有对应右边的痛点和收益是机会。"), height=800),
                 chapter=CH['touch']),
            read('touch2', T('Four kinds of gain', '四种收益'),
                 p(T("Gains are not all alike. Four statements about a phone show the four kinds.", "收益并不都一样。四条关于手机的陈述，对应四种收益。")),
                 tag(T('Four statements to tag as required, expected, desired or unexpected gains.', '四条陈述，标为必需、期望、渴望或意外的收益。'), cats, items,
                     done=T("The unexpected gain is the one customers would never name: asking them finds required and expected gains; **creating** the unexpected one is the product leadership of lesson 4 and the latent need of lesson 2.", "意外的收益是顾客永远不会说出来的：问他们能找到必需和期望的收益；**创造**意外的收益则是第 4 课的产品领先、第 2 课的潜在需求。"), height=560)),
            read('name', T('The framework, as the marker wants it', '阅卷人要的框架'),
                 p(T("The **Value Proposition Canvas** (Osterwalder) has two sides. The right is the **customer profile**, **learned from customers**; the left is the **value map**, **defined by the firm**. It is used to develop products and services customers want and value, and it fills the *value proposition* and *customer segment* blocks of the business model canvas, one canvas for each segment and proposition pair.", "**价值主张画布**（Osterwalder）有两边。右边是**客户画像**，**从顾客那里了解**；左边是**价值图**，**由企业定义**。它用来开发顾客想要并看重的产品与服务，对应商业模式画布里的*价值主张*和*客户细分*模块，每对细分与主张一张画布。")),
                 table([T('Part', '部分'), T('What it holds', '内容')],
                       [T('Jobs', '任务'), T('what customers are trying to get done: functional (mow the lawn), social (look trendy), emotional (feel secure); depend on context (cinema with a child versus a partner) and differ in importance, so rank them. They connect to the four value types of lesson 1.', '顾客想完成什么：功能性（修剪草坪）、社交性（显得时髦）、情感性（感到安心）；取决于情境（和孩子或伴侣看电影），重要性不同，要排序。它们对应第 1 课的四类价值。')],
                       [T('Pains', '痛点'), T('what annoys, costs or blocks the customer; focus on extreme pains', '惹恼、花费或阻碍顾客的东西；关注极端痛点')],
                       [T('Gains', '收益'), T('required, expected, desired, unexpected; rank by relevance', '必需、期望、渴望、意外；按相关性排序')],
                       [T('Products and services', '产品与服务'), T('what you offer: physical goods, intangible services (after-sales help, online recommendation) or financial support (payment methods)', '你提供什么：实物、无形服务（售后协助、在线推荐）或金融支持（付款方式）')],
                       [T('Pain relievers', '痛点缓解'), T('how exactly your offer eases a specific pain that matters', '你的提供具体怎样缓解某个重要痛点')],
                       [T('Gain creators', '收益创造'), T('how your offer produces a relevant gain, set against competitors', '你的提供怎样产生相关的收益，相对竞争对手而言')]),
                 p(T("**Fit** is when the value map answers the customer profile. Focus on gains and pains that matter to customers and where your offer makes a difference compared with competitors.", "**契合**就是价值图回应了客户画像。聚焦顾客在乎、而你的提供相对竞争对手能带来差别的收益和痛点。")),
                 chapter=CH['name']),
            apply_q('apply', SK, T("Take a **Who Gives a Crap** buyer. Write four sentences: one **job** (say its type), one **pain**, one **gain** (say which kind), and how the company’s offer relieves or creates them. True facts only: 50% of profits donated, direct delivery, paper-wrapped rolls, free carbon-neutral shipping on larger orders.", "以一位 **Who Gives a Crap** 的买家为例。写四句话：一个**任务**（说明类型）、一个**痛点**、一个**收益**（说明哪种），以及公司的提供怎样缓解或创造它们。只用真实事实：50% 利润捐赠、直送、纸包装、大额订单免运费、碳中和配送。"),
                    [T("Names a job with its type (social or emotional, e.g. to show I care)", "说出任务及其类型（社交或情感，如表达我在乎）"), T("A real pain (e.g. guilt about everyday purchases, or carrying bulky packs)", "一个真实的痛点（如对日常消费的愧疚，或扛笨重的包装）"),
                     T("A gain with its kind", "一个收益及其类型"), T("Links offer to pain or gain with cause and effect and a true fact", "用因果和真实事实把提供与痛点或收益联系起来")],
                    T("The buyer’s social and emotional job is to show they care, and to feel their everyday purchases are not part of the problem. The pain is guilt at spending on something that helps no one. The desired gain is that the purchase itself does good. Who Gives a Crap relieves the pain and creates the gain by donating 50% of its profits to water and sanitation projects, so each purchase is the good deed, and because the giving is certified the buyer can trust it. The expected gain of free carbon-neutral shipping on larger orders removes a further doubt.",
                      "买家的社交和情感任务是表达自己在乎，并觉得自己的日常消费不是问题的一部分。痛点是为一件无益于他人的东西花钱而内疚。渴望的收益是购买本身就在做好事。Who Gives a Crap 把 50% 的利润捐给供水和卫生项目，缓解了痛点并创造了收益：每次购买就是一次善举，而且捐赠经过认证，买家可以信任它。大额订单免运费、碳中和配送这项期望的收益，消除了另一重疑虑。"),
                    T("Type the job, name the pain, kind the gain, then link.", "标明任务类型，说出痛点，分清收益种类，再连起来。")),
            choice('neighbour', T('The look-alike', '长得像的那个'), SK,
                   T("A student fills the value map with every feature of the product. What is wrong?", "一个学生把产品所有功能都填进价值图。问题在哪？"),
                   [(T("The map should hold only what relieves pains or creates gains that matter to this customer", "价值图只该放缓解了这个顾客重要痛点、或创造了重要收益的东西"), True),
                    (T("Nothing: more features means more fit", "没问题：功能越多越契合"), T("Features nobody needs add cost, not fit.", "没人需要的功能只增加成本，不增加契合。")),
                    (T("It should list competitors’ features instead", "应该列竞争对手的功能"), T("The comparison is about relevance, not a catalogue.", "对比看的是相关性，不是目录。"))],
                   T("Fit, not features.", "要契合，不要功能堆砌。"), purpose='check', chapter=CH['neighbour']),
            recall('r1', SK, T("From lesson 7: the VPC fills which blocks of the business model canvas?", "来自第 7 课：价值主张画布填商业模式画布的哪些模块？"),
                   [(T("Customer segments and value propositions", "客户细分和价值主张"), True), (T("Cost structure and revenue", "成本结构和收入"), T("Those are on the other side of the canvas.", "那些在画布的另一侧。"))], T("The pair for each segment.", "每个细分一对。"), first=True),
            recall('r2', SK, T("From lesson 1: a social or emotional job connects to which value type?", "来自第 1 课：社交或情感任务对应哪类价值？"),
                   [(T("Symbolic or experiential value", "象征或体验价值"), True), (T("Only cost value", "只对应成本价值"), T("Jobs are wider than price.", "任务比价格宽。"))], T("Jobs link to the four value types.", "任务对应四类价值。")),
        ] + exam_three('exam', SK,
                       T("Question. (a) Explain the Value Proposition Canvas. (b) Apply it to Coles in Australia. (c) Make two recommendations.", "题目。(a) 解释价值主张画布。(b) 把它应用到澳大利亚的 Coles。(c) 给出两条建议。"),
                       (T("Write the **Explain** part.", "写**解释**部分。"),
                        [T("Two sides: customer profile (jobs, pains, gains) learned from customers and value map (products, pain relievers, gain creators) defined by the firm", "两边：客户画像（任务、痛点、收益）来自顾客；价值图（产品、痛点缓解、收益创造）由企业定义"), T("Types of job and the four kinds of gain", "任务类型和四种收益"),
                         T("Fit is the aim", "目标是契合"), T("Use for each segment and proposition pair", "每对细分与主张一张")],
                        T("The Value Proposition Canvas has a customer profile, learned from customers, and a value map, defined by the firm. The profile holds jobs (functional, social or emotional), pains, and gains (required, expected, desired, unexpected). The map holds the products and services, the pain relievers that ease specific pains, and the gain creators that produce relevant gains. The aim is fit: the map answers what matters most in the profile. It is completed for each segment and proposition pair and feeds the value proposition and customer segment blocks of the business model canvas.",
                          "价值主张画布有客户画像（从顾客那里了解）和价值图（由企业定义）。画像包括任务（功能、社交或情感）、痛点和收益（必需、期望、渴望、意外）。价值图包括产品与服务、缓解具体痛点的痛点缓解，以及产生相关收益的收益创造。目标是契合：价值图回应画像里最重要的东西。每对细分与主张填一张，并供给商业模式画布的价值主张和客户细分模块。")),
                       (T("Write the **Apply** part.", "写**应用**部分。"),
                        [T("Defines a Coles shopper segment and its jobs, pains and gains", "界定一个 Coles 购物者细分及其任务、痛点和收益"), T("Matches true Coles facts to them (same-day delivery, Own Brand, 100% Australian-grown fresh produce, Flybuys, cost savings reinvested, partnerships)", "把真实的 Coles 事实与之匹配"),
                         T("Explains cause and effect for the fit", "解释契合的因果"), T("Names a gap, a pain or gain it does not yet answer", "指出一个尚未回应的缺口，痛点或收益")],
                        T("Take working households who shop for the week. Their job is to feed the family well without losing an evening. Pains are time, and a basket that costs too much; gains are trusted fresh food and a reward for loyalty. Coles answers the time pain with same-day delivery from its own fulfilment centres, and online sales rose 26.4% in FY26, which suggests the relief matters. It answers cost with Own Brand ranges and reinvests AUD 311 million of cost savings in value, and it creates a trust gain because its Own Brand fresh meat, milk and eggs are 100% Australian-grown. Flybuys, with about 10.3 million active members, creates the reward gain. A gap is the unexpected gain: nothing here goes beyond what shoppers can already name, so the fit is strong on expected and required gains.",
                          "以每周采购一次的上班家庭为例。他们的任务是让一家人吃得好，又不牺牲一整个晚上。痛点是时间，以及一篮东西太贵；收益是可信的新鲜食品和忠诚回报。Coles 用自有履约中心的当日送达回应时间痛点，2026 财年线上销售增长 26.4%，说明这个缓解方案很重要。它用自有品牌系列回应成本，并把 3.11 亿澳元成本节省再投入价格，同时创造信任收益，因为自有品牌的鲜肉、牛奶和鸡蛋 100% 为澳大利亚产。拥有约 1,030 万活跃会员的 Flybuys 创造回报收益。缺口在意外的收益：这里没有任何东西超出购物者已能说出的，所以契合强在必需和期望的收益上。")),
                       (T("Write the **Recommend** part: exactly two.", "写**建议**部分：恰好两条。"),
                        [T("Exactly two from the analysis (explore an unexpected gain; test for a pain not yet answered)", "恰好两条，从分析里推出（探索意外的收益；检验尚未回应的痛点）"), T("Each actionable", "每条可执行"), T("A risk named", "点出风险")],
                        T("First, run small observation sessions with online shoppers at home to find pains they do not report, because the analysis shows the fit rests on gains customers can already name. The risk is time and cost, so start with one suburb. Second, rank the jobs by importance for each segment using Flybuys purchase data and fund the two highest. This focuses on what matters; the risk is relying only on past behaviour, so combine it with the observation work.",
                          "第一，在家里对线上购物者做小规模的观察，找出他们没有说出的痛点，因为分析显示契合建立在顾客已能说出的收益上。风险是时间和成本，所以先从一个郊区开始。第二，用 Flybuys 的购买数据为每个细分的任务按重要性排序，并投入最高的两项。这聚焦在重要的东西上；风险是只依赖过去的行为，所以要和观察工作结合。")),
                       ),
    )
